## 5. Database Schema (PostgreSQL DDL)

```sql
CREATE TABLE Trades (
    TradeId UUID PRIMARY KEY,
    Symbol VARCHAR(10) NOT NULL,
    TradeTimestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    Price DECIMAL(18, 8) NOT NULL,
    Quantity BIGINT NOT NULL,
    TraderId UUID NOT NULL,
    Side VARCHAR(4) NOT NULL CHECK (Side IN ('BUY', 'SELL'))
);

CREATE INDEX idx_trades_symbol_timestamp ON Trades (Symbol, TradeTimestamp);
CREATE INDEX idx_trades_traderid ON Trades (TraderId);

CREATE TABLE Alerts (
    AlertId UUID PRIMARY KEY,
    TradeId UUID REFERENCES Trades(TradeId),
    AlertTimestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    AlertType VARCHAR(50) NOT NULL,
    Description TEXT NOT NULL,
    Status VARCHAR(20) NOT NULL CHECK (Status IN ('New', 'Investigating', 'Resolved', 'FalsePositive')) DEFAULT 'New'
);

CREATE INDEX idx_alerts_tradeid ON Alerts (TradeId);
CREATE INDEX idx_alerts_alerttype ON Alerts (AlertType);

