## 7. Key Service Implementations

**7.1. SurveillanceService.cs (Surveillance.Api/Services)**

```csharp
public class SurveillanceService : ISurveillanceService
{
    private readonly ITradeRepository _tradeRepository;
    private readonly IModelInferenceService _modelInferenceService;
    private readonly IAlertingService _alertingService;

    public SurveillanceService(ITradeRepository tradeRepository, IModelInferenceService modelInferenceService, IAlertingService alertingService)
    {
        _tradeRepository = tradeRepository;
        _modelInferenceService = modelInferenceService;
        _alertingService = alertingService;
    }

    public async Task<Alert> AnalyzeTradeAsync(Guid tradeId)
    {
        // 1. Retrieve trade details from repository.
        var trade = await _tradeRepository.GetByIdAsync(tradeId);
        if (trade == null) {
            throw new SurveillanceException($"Trade with ID {tradeId} not found.");
        }

        // 2. Perform inference using ML model.
        var prediction = await _modelInferenceService.PredictAbusePatternAsync(trade);

        // 3. Generate alert if suspicious activity detected.
        if (prediction.IsAbusive)
        {
            var alert = new Alert(
                AlertId = Guid.NewGuid(),
                TradeId = trade.TradeId,
                AlertTimestamp = DateTimeOffset.UtcNow,
                AlertType = prediction.PatternName,
                Description = $"Potential {prediction.PatternName} detected for trade {trade.TradeId}. Score: {prediction.Score}",
                Status = "New"
            );

            // 4. Send alert to alerting service.
            await _alertingService.SendAlertAsync(alert);
            return alert;
        }

        return null; // No alert generated
    }
}
```

